from research_helpers import *
a=ev('https://microport.com/assets/blog/2025-Annual-Report.pdf','2025 parent annual report published 2026 confirms surgical robotics business and commercial installations. Parent association through group; no direct parent manufacturing assertion.')
b=ev('https://ir.medbotsurgical.com/media/jwcbfiqy/microport-medbot-fy25-presentation-0402.pdf','MedBot March2026 results identifies separate multiport, remote and single-port Toumai systems, SkyWalker, R-ONE, Mona Lisa, DFVision and UniPath. UniPath NMPA approved December2025; commercial rollout planned from2026. MicroGenius demonstrated in animal autonomous surgery only.')
c=ev('https://microport.com/healthcare-professional/surgical-robots','Current parent catalogue confirms surgical robots and compatible DFVision imaging accessory. Country-specific availability; investigational FDA exemption not general US market approval.')
d=ev('https://www.medbotsurgical.com/en/news/224.html','R-ONE marketed through Robocath/MedBot CathBot joint venture, China NMPA approval December2023. Not assumed wholly owned original invention by parent.')
e=ev('https://ir.medbotsurgical.com/media/lrnnevw3/2021-annual-report.pdf','Historical subsidiary annual report confirms Madam Curie automated surgical research platform and December2021 animal study. Current clinical/commercial availability unresolved.')
products=[]
for name,desc,life,source,typ,aliases in [
 ('Toumai multi-port laparoscopic surgical robot','Robot-assisted laparoscopic system. Indications retained within one product rather than duplicate indication rows.','commercial',b,'product',['Toumai laparoscopic surgical robot']),
 ('Toumai remote laparoscopic surgical system','Distinct remote surgical system in manufacturer pipeline; authorization varies by jurisdiction. FDA IDE is investigational permission.','commercial',b,'product',[]),
 ('Toumai single-port laparoscopic surgical robot','Distinct single-port robotic platform; manufacturer reports NMPA approval February2025 and Abu Dhabi installation.','commercial',b,'product',[]),
 ('SkyWalker orthopedic surgical robot','Robot-assisted knee and hip arthroplasty platform with commercial installations.','commercial',c,'product',['Honghu orthopedic surgical robot']),
 ('R-ONE vascular interventional robot','Coronary intervention robot commercialized through CathBot joint venture with Robocath.','commercial',d,'product',[]),
 ('iSRobot Mona Lisa','Robot-assisted transperineal prostate biopsy system offered through international collaboration.','commercial',c,'product',["iSR’obot Mona Lisa"]),
 ('DFVision 3D electronic laparoscope','Integrated visualization accessory compatible with Toumai robotic platform; not a standalone surgical robot.','commercial',c,'product',[]),
 ('UniPath electronic bronchoscopic surgical robot','Trans-bronchial robotic diagnosis and treatment platform; approved December2025, actual commercial rollout not established by reviewed planned-launch statement.','unknown',b,'product',['UniPath','独道']),
 ('MicroGenius multimodal autonomous surgical model','Robotics control model evaluated in animal autonomous-surgery research. No human autonomous-surgery approval inferred.','research',b,'technology',[]),
 ('Madam Curie automated surgical platform','Historical automated surgical research platform demonstrated in animal study; current continuation unverified.','unknown',e,'technology',[])]:
 products.append(p('MicroPort '+name,desc,source,life,typ=typ,sector='robotics',sub='medical_robotics',aliases=aliases,roles=['commercial_partner'],attributes={'corporate_scope':'parent_group_association','regulatory_scope':'jurisdiction_and_indication_specific'},evidence=[a,source]))
co=company('MicroPort Scientific Corp',products,[a,b,c,d,e],'Ten surgical robotics products, integrated visualization accessory and research platforms reviewed from current parent/subsidiary sources. Toumai multi-port, remote and single-port separately named; no generic Toumai family duplicate added. UniPath approval is not proof of actual planned2026 rollout; unknown availability. Need broader group biotech/research products, exact robot generations and instrument SKUs, additional historic spine/TAVR/puncture programmes, updated UniPath rollout and global rights/clearances. General stents, orthopedic implants and pacemakers do not automatically fall within four target sectors. Scan partial.')
(out/'batch-0167.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
